#include "enginebridge.h"
#include <QCoreApplication>
#include <iostream>
using namespace retro;
int main(int argc,char** argv){QCoreApplication app(argc,argv);if(argc<2){std::cout<<"Pass an installed Stockfish path to run the optional UCI integration test.\n";return 0;}QString path=QString::fromLocal8Bit(argv[1]);Chess g;QStringList moves{"f2f3","e7e5","g2g4"};std::vector<uint64_t> keys{g.key()};for(auto code:moves){for(auto m:g.legal())if(QString::fromStdString(uci(m))==code){g.make(m);keys.push_back(g.key());break;}}auto cancel=std::make_shared<std::atomic_bool>(false);auto result=computeMove(g,{8,450},keys,cancel,path,5,moves);if(!result.error.isEmpty()||result.engine!="Stockfish / UCI"||uci(result.result.move)!="d8h4"){std::cerr<<"UCI TEST FAILED: "<<result.error.toStdString()<<" "<<uci(result.result.move)<<"\n";return 1;}std::cout<<"Stockfish: "<<uci(result.result.move)<<" (mate), depth "<<result.result.depth<<", nodes "<<result.result.nodes<<"\n";auto fallback=computeMove(g,{5,300},keys,cancel,"/nonexistent/stockfish",5,moves);if(!fallback.result.move.valid()||fallback.engine!="C++ AI"||fallback.error.isEmpty()){std::cerr<<"Fallback failed\n";return 1;}std::cout<<"Missing UCI engine falls back to built-in C++ AI.\n";cancel->store(true);auto stopped=computeMove(g,{8,1000},keys,cancel,path,5,moves);if(stopped.result.move.valid()){std::cerr<<"Cancellation failed\n";return 1;}std::cout<<"UCI cancellation passed.\nALL UCI TESTS PASSED\n";return 0;}
